"""Illustrative scenarios, not reconstructed observations or classification rules."""
import streamlit as st
import plotly.graph_objects as go

SCENARIOS={
'build_up':dict(before='Blue already has settled possession near its own goal. Orange has two players pressing the ball while the rest of its team stays farther back.',why='The defining idea is controlled possession while establishing an attack from deeper territory. A sideways pass can be part of build-up; forward speed alone does not define it.',contrast='If blue had just won possession and immediately attacked, the recent turnover would make fast transition relevant. No turnover is shown here.',bridge='Ball starting position and team width describe where possession begins and how spread out the team is. Phase averages cannot show the exact passing order.',attack=[(18,22),(24,48),(39,32),(48,55)],defend=[(29,24),(34,45),(57,27),(60,49)],steps=[('Possession established','Blue 1 has the ball. Blue 2 offers a wide outlet; blue 3 offers a central option. Orange 1 is close enough to press.',(18,22),None),('Use the outlet','Blue 1 passes to blue 2, away from the nearest presser. Blue still controls the ball in its own half.',(24,48),(18,22)),('Find the next pass','Blue 2 plays into blue 3. The attack advances through controlled passes rather than one long forward delivery.',(39,32),(24,48))]),
'creation':dict(before='Blue has established possession in the attacking half. Orange is already organized between the ball and its goal.',why='Blue is trying to develop an opening against an organized defense. This example emphasizes changing the angle of attack, rather than a recent turnover or an immediate shot.',contrast='The final shot would be finishing. Moving the ball near the penalty area does not, by itself, prove the entire phase is finishing.',bridge='Attacking width, player spacing, and defenders near the ball summarize the shape of this situation. They do not reveal which defender follows a pass.',attack=[(59,28),(73,55),(82,36),(92,20)],defend=[(71,30),(82,49),(89,34),(94,23)],steps=[('Assess the defense','Blue 1 faces orange 1. The central route is crowded, while blue 2 is available out wide.',(59,28),None),('Change the angle','Blue 1 passes wide to blue 2. The new ball position creates a different angle into the central area.',(73,55),(59,28)),('Develop an opening','Blue 2 passes toward blue 3 between defenders. The example ends at the receiving position; it does not claim a shot or a goal.',(82,36),(73,55))]),
'direct_attack':dict(before='Blue has possession in its own half. A forward teammate is available much farther upfield. This example does not start with a turnover.',why='The ball moves a large distance toward the opponent’s goal in one delivery. The quick forward route is the distinguishing idea in the paper’s description.',contrast='Direct attack and fast transition can look similar. To discuss a transition, you also need to know that possession was recently gained; distance traveled alone cannot tell you that.',bridge='Ball progress and duration help describe rapid forward movement. In the actual dataset, progress is signed x displacement; its sign alone does not tell us whether a team attacked forward.',attack=[(25,24),(45,48),(76,32),(87,48)],defend=[(42,28),(58,45),(81,28),(91,43)],steps=[('Look forward','Blue 1 has the ball and blue 3 is positioned beyond the midfield players.',(25,24),None),('Play long','Blue 1 sends the ball directly to blue 3, bypassing the nearby blue 2 option. The arrow represents a pass, not a player run.',(76,32),(25,24)),('Continue the attack','Blue 3 receives and passes to blue 4 farther forward. A completed shot is not part of this example.',(87,48),(76,32))]),
'fast_transition':dict(before='Orange has just lost possession. Blue 1 wins the ball while several orange players are still ahead of the turnover location and must recover.',why='The attack begins immediately after a change of possession. That preceding event is essential context; the shape of the pitch at one instant cannot establish it.',contrast='A long forward pass during settled possession could be direct attack without demonstrating a fast transition. Here the turnover is explicitly part of the scenario.',bridge='The paper finds fast transitions difficult to identify. Averages of position and spacing lose the order of events, including the moment possession changes.',attack=[(42,33),(61,47),(79,29),(83,54)],defend=[(35,22),(39,49),(67,25),(87,40)],steps=[('Possession changes','Blue 1 has just won the ball. Orange 1 and 2 are behind the ball relative to blue’s attacking direction.',(42,33),None),('Attack immediately','Blue 1 releases blue 2 before orange has reorganized. This quick response to the turnover is the point of the example.',(61,47),(42,33)),('Use the available space','Blue 2 passes to blue 3 farther forward. The defense still has players recovering; the scenario ends before a shot.',(79,29),(61,47))]),
'finishing':dict(before='Blue already has the ball close to the opponent’s goal. A wide player can pass to a teammate in a shooting position.',why='This scenario focuses on the final attacking action near goal. The shot is shown, but its outcome is deliberately unspecified: finishing does not mean scoring.',contrast='Working the ball around to find an opening is creation. Here the selected moment includes the final delivery and shot attempt.',bridge='Ball location, nearby defenders, and attackers ahead of the ball describe the setting. The saved summaries do not identify the shooter or prove a shot occurred in any particular recorded example.',attack=[(87,54),(94,35),(83,21),(76,40)],defend=[(90,48),(92,29),(85,38),(102,34)],steps=[('Prepare the final ball','Blue 1 has possession near the side of the penalty area. Blue 2 is central; orange 4 represents the goalkeeper.',(87,54),None),('Find the shooter','Blue 1 passes to blue 2 in front of goal. This is the last pass in the illustrated move.',(94,35),(87,54)),('Attempt the shot','Blue 2 shoots toward goal. The diagram does not show whether the goalkeeper saves it or the ball goes in.',(105,34),(94,35))])}

def render(tactic):
 s=SCENARIOS[tactic]
 st.write('**Before this phase:** '+s['before'])
 step=st.radio('Walk through the example',[0,1,2],format_func=lambda i:f'{i+1}. {s["steps"][i][0]}',horizontal=True,key='teaching_step_'+tactic)
 title,description,ball,previous=s['steps'][step]
 st.markdown('**'+title+'**');st.write(description)
 fig=go.Figure()
 fig.add_shape(type='rect',x0=0,y0=0,x1=105,y1=68,line_color='white',fillcolor='#285943')
 fig.add_shape(type='line',x0=52.5,y0=0,x1=52.5,y1=68,line_color='white')
 fig.add_shape(type='circle',x0=43.35,y0=24.85,x1=61.65,y1=43.15,line_color='white')
 for x0,x1 in [(0,16.5),(88.5,105)]:fig.add_shape(type='rect',x0=x0,y0=13.84,x1=x1,y1=54.16,line_color='white')
 for x0,x1 in [(-2,0),(105,107)]:fig.add_shape(type='rect',x0=x0,y0=30.34,x1=x1,y1=37.66,line_color='#173e32')
 for team,color,symbol in [('attack','#b9ddff','circle'),('defend','#f9a56a','square')]:
  pts=s[team];name='Blue: attacking players' if team=='attack' else 'Orange: defending players'
  fig.add_trace(go.Scatter(x=[p[0] for p in pts],y=[p[1] for p in pts],mode='markers+text',text=['1','2','3','4'],textposition='middle center',textfont=dict(color='#13251c'),marker=dict(size=25,color=color,symbol=symbol,line=dict(color='#13251c',width=1)),name=name,hovertemplate=name+' %{text}<extra></extra>'))
 if previous:fig.add_annotation(x=ball[0],y=ball[1],ax=previous[0],ay=previous[1],xref='x',yref='y',axref='x',ayref='y',arrowhead=3,arrowwidth=3,arrowcolor='#ffe071')
 fig.add_trace(go.Scatter(x=[ball[0]],y=[ball[1]+2.4],mode='markers',marker=dict(size=11,color='white',line=dict(color='black',width=2)),name='Ball (offset for visibility)',hoverinfo='name'))
 fig.update_layout(height=420,margin=dict(l=12,r=12,t=45,b=65),title='Blue attacks → toward the right-hand goal',legend=dict(orientation='h',y=-.08),paper_bgcolor='white',plot_bgcolor='white',xaxis=dict(range=[-4,109],visible=False,fixedrange=True),yaxis=dict(range=[-2,70],visible=False,scaleanchor='x',scaleratio=1,fixedrange=True))
 st.plotly_chart(fig,width='stretch',config={'displayModeBar':False},key='concept_pitch')
 st.caption('Teaching illustration, not recorded match data. Only four players per team are shown; their positions stay fixed to isolate the ball actions. The yellow arrow shows the selected pass or shot, not a run. Step numbers indicate order, not elapsed time. No model is evaluated on this diagram.')
 st.write('**Why this illustrates the label:** '+s['why'])
 st.write('**How to distinguish it:** '+s['contrast'])
 st.write('**Connection to the paper:** '+s['bridge'])
 st.caption('Label descriptions follow the paper’s tactical-phase definitions. The specific players, positions, and actions are invented teaching examples, not SkillCorner labeling rules or numerical thresholds.')
